t3template.addControl({ id: 'minMinutes', label: 'Min Minutes', type: 'slider', min: 0, max: 60, step: 1, default: 0, panel: 'Trip Filter', onChange(v, t) { const filters = { ...t.instances.grid.get().filters }; if (v > 0) filters.duration_min = '>=' + v; else delete filters.duration_min; t.instances.grid.set({ filters }); t.refresh(); } });
t3template.addPreset('Long Trips', { filters: { duration_min: '>=20' }, sort: { id: 'duration_min', dir: 'desc' }, pivot: { by: 'city', value: 'duration_min', agg: 'mean' } });
t3template.addToolbarButton('Min 10 Minutes', (t) => t.setValues({ filters: { ...t.getValues().filters, duration_min: '>=10' } }, 'Min 10 Minutes'), { shortcut: 'shift+m' });
